-- Sample data for the dev project and the database tests (TECH_SPEC §10): the coach,
-- 12 customer accounts, their students, 13 groups with opening balances, payments,
-- bookings around the week of Mon 28 Sep 2026, and the weekly open hours.
-- Times are MYT (+08). Tests pin the clock at Sat 26 Sep 2026 12:00 MYT.
--
-- NEVER load this into production (prompt 12 pushes migrations without the seed).
-- Every account's password is `swim-test-2026`. The repo is public, so these
-- passwords are too: they are for the dev project only.
--
-- Loaded on swimclass-dev by `npx supabase db push --include-seed` (first time) or
-- `npx supabase db reset --linked` (start again), and locally by `npx supabase db reset`
-- (Docker). See docs/DEV_SETUP.md §3.
-- Fixed ids so tests and supabase/snippets/shift-seed.sql can find rows:
--   accounts a0…, students b0…, groups c0…, bookings d0…, payments e0…

-- Production is marked with the role `swimclass_production` (prompt 12), so loading
-- this there by mistake stops before any sample account (with its public password)
-- is created.
do $$
begin
  if exists (select 1 from pg_catalog.pg_roles where rolname = 'swimclass_production') then
    raise exception 'This is the production database: seed.sql is for swimclass-dev only.';
  end if;
end;
$$;

-- The seed loads only into an empty database. To load it again, reset:
-- `npx supabase db reset --linked` also clears the auth users (DEV_SETUP §3).

-- Accounts. The on_auth_user_created trigger creates each profile from the metadata.
insert into auth.users (
  instance_id, id, aud, role, email, encrypted_password, email_confirmed_at,
  raw_app_meta_data, raw_user_meta_data, created_at, updated_at,
  confirmation_token, recovery_token, email_change_token_new, email_change
)
select
  '00000000-0000-0000-0000-000000000000',
  u.id,
  'authenticated',
  'authenticated',
  u.username || '@example.com',
  extensions.crypt('swim-test-2026', extensions.gen_salt('bf')),
  now(),
  '{"provider": "email", "providers": ["email"]}',
  jsonb_build_object('username', u.username, 'display_name', u.display_name, 'phone', u.phone),
  now(),
  now(),
  '', '', '', ''
from (values
  ('a0000000-0000-4000-8000-000000000001'::uuid, 'herman',   'Herman',   '012-000 0001'),
  ('a0000000-0000-4000-8000-000000000002'::uuid, 'meiling',  'Mei Ling', '012-000 0002'),
  ('a0000000-0000-4000-8000-000000000003'::uuid, 'farah',    'Farah',    '012-000 0003'),
  ('a0000000-0000-4000-8000-000000000004'::uuid, 'weijie',   'Wei Jie',  '012-000 0004'),
  ('a0000000-0000-4000-8000-000000000005'::uuid, 'priya',    'Priya',    '012-000 0005'),
  ('a0000000-0000-4000-8000-000000000006'::uuid, 'zulaikha', 'Zulaikha', '012-000 0006'),
  ('a0000000-0000-4000-8000-000000000007'::uuid, 'junhao',   'Jun Hao',  '012-000 0007'),
  ('a0000000-0000-4000-8000-000000000008'::uuid, 'grace',    'Grace',    '012-000 0008'),
  ('a0000000-0000-4000-8000-000000000009'::uuid, 'ethan',    'Ethan',    '012-000 0009'),
  ('a0000000-0000-4000-8000-000000000010'::uuid, 'kai',      'Kai',      '012-000 0010'),
  ('a0000000-0000-4000-8000-000000000011'::uuid, 'daniel',   'Daniel',   '012-000 0011'),
  ('a0000000-0000-4000-8000-000000000012'::uuid, 'aina',     'Aina',     '012-000 0012'),
  ('a0000000-0000-4000-8000-000000000013'::uuid, 'nurul',    'Nurul',    '012-000 0013')
) as u (id, username, display_name, phone);

-- Email sign-in needs an identity row per user.
insert into auth.identities (
  id, user_id, provider_id, identity_data, provider, last_sign_in_at, created_at, updated_at
)
select
  gen_random_uuid(),
  u.id,
  u.id::text,
  jsonb_build_object('sub', u.id::text, 'email', u.email, 'email_verified', true),
  'email',
  now(),
  now(),
  now()
from auth.users u
where u.id::text like 'a0000000-0000-4000-8000-0000000000__';

